# ── VIP / session helpers ──────────────────────────────────────────────────────

def load_vip() -> dict:
    try:
        return json.loads(VIP_FILE.read_text()) if VIP_FILE.exists() else {}
    except Exception as e:
        logger.warning(f"Could not read VIP data, using empty list: {e}")
        return {}

def save_vip(data: dict):
    temp = VIP_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data, indent=2, ensure_ascii=False))
    temp.replace(VIP_FILE)

def is_vip(user_id: int) -> bool:
    vip = load_vip()
    uid = str(user_id)
    if uid not in vip:
        return False
    expiry = vip[uid].get("expiry")
    if expiry is None:
        return True
    try:
        return datetime.fromisoformat(expiry) > datetime.now(timezone.utc)
    except Exception:
        return False

def load_sessions() -> dict:
    try:
        return json.loads(SESSIONS_FILE.read_text()) if SESSIONS_FILE.exists() else {}
    except Exception as e:
        logger.warning(f"Could not read session data, using empty sessions: {e}")
        return {}

def save_sessions(data: dict):
    temp = SESSIONS_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data, indent=2))
    temp.replace(SESSIONS_FILE)

def touch_session(user_id: int):
    s = load_sessions()
    s[str(user_id)] = datetime.now(timezone.utc).isoformat()
    save_sessions(s)

def count_active_sessions() -> int:
    s = load_sessions()
    cutoff = datetime.now(timezone.utc) - timedelta(minutes=30)
    return sum(1 for ts in s.values() if datetime.fromisoformat(ts) > cutoff)

def count_expiring_soon() -> int:
    vip = load_vip()
    cutoff = datetime.now(timezone.utc) + timedelta(days=3)
    count = 0
    for d in vip.values():
        exp = d.get("expiry")
        if exp:
            try:
                dt = datetime.fromisoformat(exp)
                if datetime.now(timezone.utc) < dt < cutoff:
                    count += 1
            except Exception:
                pass
    return count

def count_active_vip() -> int:
    vip = load_vip()
    now = datetime.now(timezone.utc)
    count = 0
    for d in vip.values():
        exp = d.get("expiry")
        if exp is None:
            count += 1
        else:
            try:
                if datetime.fromisoformat(exp) > now:
                    count += 1
            except Exception:
                pass
    return count


# ── One-hour daily free access ─────────────────────────────────────────────────

def _today_key() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d")

def load_free_access() -> dict:
    try:
        return json.loads(FREE_FILE.read_text()) if FREE_FILE.exists() else {}
    except Exception as e:
        logger.warning(f"Could not read free-access data, using empty list: {e}")
        return {}

def save_free_access(data: dict):
    temp = FREE_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data, indent=2, ensure_ascii=False))
    temp.replace(FREE_FILE)

def _free_record(data: dict, user_id: int) -> dict | None:
    record = data.get(str(user_id))
    if not isinstance(record, dict) or not record.get("enabled", False):
        return None
    if record.get("date") != _today_key():
        record.update({
            "date": _today_key(),
            "used_seconds": 0,
            "active": False,
            "started_at": None,
        })
    return record

def _free_used_seconds(record: dict) -> int:
    used = max(0, int(record.get("used_seconds", 0)))
    if record.get("active") and record.get("started_at"):
        try:
            started = datetime.fromisoformat(record["started_at"])
            used += max(0, int((datetime.now(timezone.utc) - started).total_seconds()))
        except Exception:
            pass
    return used

def free_remaining_seconds(user_id: int) -> int:
    data = load_free_access()
    old_date = data.get(str(user_id), {}).get("date")
    record = _free_record(data, user_id)
    if record is None:
        return 0
    remaining = max(0, FREE_DAILY_SECONDS - _free_used_seconds(record))
    if remaining == 0 and record.get("active"):
        record["used_seconds"] = FREE_DAILY_SECONDS
        record["active"] = False
        record["started_at"] = None
        save_free_access(data)
    elif old_date != record.get("date"):
        save_free_access(data)
    return remaining

def free_access_enabled(user_id: int) -> bool:
    return free_remaining_seconds(user_id) > 0

def has_signal_access(user_id: int) -> bool:
    return is_vip(user_id) or free_access_enabled(user_id)

def start_free_timer(user_id: int) -> bool:
    data = load_free_access()
    record = _free_record(data, user_id)
    if record is None or _free_used_seconds(record) >= FREE_DAILY_SECONDS:
        return False
    if not record.get("active"):
        record["active"] = True
        record["started_at"] = datetime.now(timezone.utc).isoformat()
        save_free_access(data)
    return True

def pause_free_timer(user_id: int) -> int:
    data = load_free_access()
    record = _free_record(data, user_id)
    if record is None:
        return 0
    record["used_seconds"] = min(FREE_DAILY_SECONDS, _free_used_seconds(record))
    record["active"] = False
    record["started_at"] = None
    save_free_access(data)
    return max(0, FREE_DAILY_SECONDS - record["used_seconds"])

def format_free_time(seconds: int) -> str:
    return f"{seconds // 60}m {seconds % 60}s"

def count_free_access() -> int:
    return sum(
        1 for record in load_free_access().values()
        if isinstance(record, dict) and record.get("enabled", False)
    )

# ── Channel signal storage ─────────────────────────────────────────────────────

def save_channel_signal(signal: str, source_timestamp: str | None = None):
    data = {
        "signal": signal,
        "timestamp": source_timestamp or datetime.now(timezone.utc).isoformat(),
        "fetched_at": datetime.now(timezone.utc).isoformat(),
        "source_timestamp": source_timestamp,
    }
    temp = CHANNEL_SIG_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(data))
    temp.replace(CHANNEL_SIG_FILE)
    source_hist = load_source_history()
    if not source_hist or (
        source_hist[-1].get("signal") != signal
        or source_hist[-1].get("timestamp") != data["timestamp"]
    ):
        source_hist.append({
            "signal": signal,
            "timestamp": data["timestamp"],
        })
    temp = SOURCE_HIST_FILE.with_suffix(".tmp")
    temp.write_text(json.dumps(source_hist[-120:], indent=2))
    temp.replace(SOURCE_HIST_FILE)
    logger.info(f"📡 Channel signal saved: {signal}")

def get_channel_signal() -> str | None:
    if not CHANNEL_SIG_FILE.exists():
        return None
    try:
        data = json.loads(CHANNEL_SIG_FILE.read_text())
        ts   = datetime.fromisoformat(data["timestamp"])
        age  = (datetime.now(timezone.utc) - ts).total_seconds() / 60
        if age <= CHANNEL_CACHE_MAX_AGE_MIN:
            return data["signal"]
    except Exception:
        pass
    return None


def load_source_history() -> list:
    try:
        data = json.loads(SOURCE_HIST_FILE.read_text()) if SOURCE_HIST_FILE.exists() else []
        return data if isinstance(data, list) else []
    except Exception as e:
        logger.warning("Could not read source history: %s", e)
        return []


def load_user_rounds() -> dict:
    try:
        data = json.loads(USER_ROUNDS_FILE.read_text()) if USER_ROUNDS_FILE.exists() else {}
        return data if isinstance(data, dict) else {}
    except Exception as e:
        logger.warning("Could not read user round history: %s", e)
