async def _do_add_vip(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    ctx.user_data["state"] = None
    parts = text.strip().split()
    if len(parts) != 2:
        await update.message.reply_text("❌ Format: `USER_ID DAYS`", parse_mode=ParseMode.MARKDOWN); return
    try:
        uid = str(int(parts[0])); days = int(parts[1])
    except ValueError:
        await update.message.reply_text("❌ ဂဏန်းဖြစ်ရပါမည်"); return
    expiry     = None if days == 0 else (datetime.now(timezone.utc) + timedelta(days=days)).isoformat()
    expiry_str = "♾ Lifetime" if expiry is None else expiry[:10]
    try:
        chat = await ctx.bot.get_chat(int(uid))
        first_name = chat.first_name or ""; username = chat.username or ""
    except Exception:
        first_name = "Unknown"; username = ""
    vip = load_vip()
    vip[uid] = {"first_name": first_name, "username": username, "expiry": expiry,
                "added_by": update.effective_user.id, "added_at": datetime.now(timezone.utc).isoformat()}
    save_vip(vip)
    await update.message.reply_text(
        f"✅ *VIP Added!*\n\n👤 ID: `{uid}`\n📛 Name: {first_name}\n📅 Expiry: {expiry_str}",
        parse_mode=ParseMode.MARKDOWN,
    )
    try:
        await _send_photo_retry(
            ctx.bot,
            int(uid),
            "vip_welcome",
            caption=(f"🎉 *ကြိုဆိုပါတယ် {first_name}!*\n\n👑 သင်သည် *VIP Member* ဖြစ်သွားပါပြီ!\n"
                     f"━━━━━━━━━━━━━━━━━━━━\n📅 သက်တမ်း : {expiry_str}\n\n🎯 */start* နှိပ်၍ Signals ရယူပါ!"),
            parse_mode=ParseMode.MARKDOWN,
        )
    except Exception as e:
        logger.warning(f"Could not notify VIP {uid}: {e}")

async def _do_grant_free(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    ctx.user_data["state"] = None
    try:
        uid = str(int(text.strip()))
    except ValueError:
        await update.message.reply_text("❌ User ID က ဂဏန်းဖြစ်ရပါမည်")
        return

    data = load_free_access()
    existing = data.get(uid)
    today = _today_key()
    if not isinstance(existing, dict) or existing.get("date") != today:
        data[uid] = {
            "enabled": True,
            "date": today,
            "used_seconds": 0,
            "active": False,
            "started_at": None,
            "granted_by": update.effective_user.id,
            "granted_at": datetime.now(timezone.utc).isoformat(),
        }
    else:
        existing["enabled"] = True
        existing["granted_by"] = update.effective_user.id
        existing["granted_at"] = datetime.now(timezone.utc).isoformat()
    save_free_access(data)

    remaining = free_remaining_seconds(int(uid))
    await update.message.reply_text(
        f"✅ *Daily Free Access ပေးပြီးပါပြီ*\n\n"
        f"👤 User ID: `{uid}`\n"
        f"🎁 ယနေ့ကျန်ချိန်: *{format_free_time(remaining)}*\n\n"
        "Signal တောင်းမှ timer စပါမယ်။ Stop လုပ်ထားရင် အချိန်မဆက်တွက်ပါ။",
        parse_mode=ParseMode.MARKDOWN,
    )
    try:
        await _send_text_retry(
            ctx.bot,
            int(uid),
            "🎁 Admin က သင့်အတွက် ယနေ့ Daily Free Access ၁ နာရီ ခွင့်ပြုထားပါတယ်။\n"
            "Signal တောင်းမှ timer စပါမယ်။",
        )
    except Exception as e:
        logger.warning(f"Could not notify free-access user {uid}: {e}")

async def _do_remove_free(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    ctx.user_data["state"] = None
    try:
        uid = str(int(text.strip()))
    except ValueError:
        await update.message.reply_text("❌ User ID က ဂဏန်းဖြစ်ရပါမည်")
        return

    data = load_free_access()
    record = data.get(uid)
    if not isinstance(record, dict) or not record.get("enabled", False):
        await update.message.reply_text(
            f"❌ User `{uid}` အတွက် Free Access မရှိပါ",
            parse_mode=ParseMode.MARKDOWN,
        )
        return
    record["enabled"] = False
    record["active"] = False
    record["started_at"] = None
    save_free_access(data)
    await update.message.reply_text(
        f"✅ *Free Access ဖယ်ပြီးပါပြီ*\n\n👤 User ID: `{uid}`",
        parse_mode=ParseMode.MARKDOWN,
    )

async def _do_remove_vip(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    ctx.user_data["state"] = None
    try: uid = str(int(text.strip()))
    except ValueError:
        await update.message.reply_text("❌ ဂဏန်းဖြစ်ရပါမည်"); return
    vip = load_vip()
    if uid not in vip:
        await update.message.reply_text(f"❌ User `{uid}` VIP List ထဲမရှိပါ", parse_mode=ParseMode.MARKDOWN); return
    name = vip[uid].get("first_name", "Unknown"); del vip[uid]; save_vip(vip)
    await update.message.reply_text(f"✅ *VIP Removed!*\n\n👤 ID: `{uid}`\n📛 Name: {name}", parse_mode=ParseMode.MARKDOWN)

async def _do_broadcast(update: Update, ctx: ContextTypes.DEFAULT_TYPE, text: str):
    ctx.user_data["state"] = None
    vip = load_vip(); success = 0; fail = 0
    for uid in list(vip.keys()):
        try:
            await ctx.bot.send_message(int(uid), f"📢 *Broadcast*\n\n{text}", parse_mode=ParseMode.MARKDOWN)
            success += 1
        except Exception: fail += 1
        await asyncio.sleep(0.05)
    await update.message.reply_text(f"📢 *Broadcast Complete!*\n\n✅ Sent: {success}\n❌ Failed: {fail}", parse_mode=ParseMode.MARKDOWN)


async def error_handler(update: object, context: ContextTypes.DEFAULT_TYPE):
    """Log unexpected update errors so one bad update cannot stop polling."""
    error = context.error
    if error:
        logger.error("Unhandled Telegram update error: %s", error, exc_info=error)


# ── Bot setup ──────────────────────────────────────────────────────────────────

async def post_init(app: Application):
    await app.bot.set_my_commands([
        BotCommand("start", "Bot စတင်ရန် / ကြိုဆိုစာ"),
        BotCommand("myid",  "သင်၏ Telegram ID ကြည့်ရန်"),
        BotCommand("stats", "WIN/LOSS နှင့် Win rate ကြည့်ရန်"),
    ])
    for admin_id in ADMIN_IDS:
        await _set_admin_commands(app.bot, admin_id)
    logger.info("✅ Bot initialized")

def main():
    validate_configuration()
    app = Application.builder().token(BOT_TOKEN).post_init(post_init).build()
    app.add_handler(CommandHandler("start", cmd_start))
    app.add_handler(CommandHandler("myid",  cmd_myid))
    app.add_handler(CommandHandler("stats", cmd_stats))
    app.add_handler(CommandHandler("admin", cmd_admin))
    app.add_handler(CallbackQueryHandler(handle_callback))
    app.add_handler(MessageHandler(
        (filters.Chat(username=SIGNAL_CHANNEL) & filters.TEXT) |
        (filters.Chat(username=SIGNAL_CHANNEL) & filters.CAPTION) |
        (filters.UpdateType.CHANNEL_POSTS & filters.Chat(username=SIGNAL_CHANNEL)),
        handle_channel_post
    ))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, handle_message))
    app.add_error_handler(error_handler)
    logger.info("🤖 Dr Thet Pyinn Signals Bot starting...")
    app.run_polling(allowed_updates=Update.ALL_TYPES, drop_pending_updates=True)

if __name__ == "__main__":
    main()